// Turns web/dist (one app.js + one app.css) into src/next-app.generated.js, which the Worker imports.
// Run through `cd web && bun run build`. The generated file is committed, so deploys need no build step.
import {readFileSync, writeFileSync, existsSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'web', 'dist');
const js = readFileSync(join(dist, 'app.js'), 'utf8');
const css = existsSync(join(dist, 'app.css')) ? readFileSync(join(dist, 'app.css'), 'utf8') : '';
// "</script" inside the script would end it early, and "<!--" can start a comment inside it.
const safe = (s) => s.replace(/<\/(script|style)/gi, '<\\/$1').replace(/<!--/g, '<\\!--');
const out = '// GENERATED by scripts/embed-web.mjs from web/. Do not edit by hand.\n'
  + 'export const NEXT_JS = ' + JSON.stringify(safe(js)) + ';\n'
  + 'export const NEXT_CSS = ' + JSON.stringify(safe(css)) + ';\n';
writeFileSync(join(root, 'src', 'next-app.generated.js'), out);
console.log('next-app.generated.js:', Math.round(out.length / 1024), 'KB (js ' + Math.round(js.length / 1024) + ' KB, css ' + Math.round(css.length / 1024) + ' KB)');
